<?php
declare(strict_types=1);
namespace HardnessMcp\Tools\Product\Prices;
use HardnessMcp\Context\ExecutionContext;
use HardnessMcp\Tenant\ResolvedTenantContext;
use PhpOffice\PhpSpreadsheet\Cell\DataType;
use PhpOffice\PhpSpreadsheet\Spreadsheet;
use PhpOffice\PhpSpreadsheet\Writer\Xlsx;
use PDO;
final class PriceReportExportService
{
    private PDO $pdo; private ResolvedTenantContext $tenant; private string $shareDirectory; private string $erpRootPath;
    public function __construct(PDO $pdo, ResolvedTenantContext $tenant, string $erpRootPath, ?string $shareDirectory=null){
        if(!class_exists(Spreadsheet::class))require_once dirname(__DIR__,5).'/bibliotecas/composer/vendor/autoload.php';
        $this->pdo=$pdo;$this->tenant=$tenant;$this->erpRootPath=rtrim($erpRootPath,'/');$this->shareDirectory=$shareDirectory??$this->erpRootPath.'/whatsapp';
    }
    public function export(string $publicId, ExecutionContext $context): array
    {
        $batch=$this->query('SELECT * FROM MCP020 WHERE MCP020_Public_Id=? AND MCP020_C004_Id=?',[$publicId,$context->getCompanyId()])->fetch(PDO::FETCH_ASSOC);
        if(!$batch)throw new \RuntimeException('batch_unavailable');
        $actorId=(int)($batch['MCP020_C007_Id_Aprovacao']??$batch['MCP020_C007_Id']);$actor=$this->query('SELECT C007_Nome,C007_Login FROM C007 WHERE C007_Id=?',[$actorId])->fetch(PDO::FETCH_ASSOC);$batch['actor_name']=$this->actorName(is_array($actor)?$actor:[],$actorId);
        $rows=$this->query('SELECT * FROM MCP021 WHERE MCP021_MCP020_Id=? ORDER BY MCP021_Linha',[$batch['MCP020_Id']])->fetchAll(PDO::FETCH_ASSOC);
        if(!is_dir($this->shareDirectory)&&!mkdir($this->shareDirectory,0750,true)&&!is_dir($this->shareDirectory))throw new \RuntimeException('export_unavailable');
        if(!is_writable($this->shareDirectory))throw new \RuntimeException('export_unavailable');
        $archiveDirectory=$this->archiveDirectory($batch);if(!is_dir($archiveDirectory)&&!mkdir($archiveDirectory,0750,true)&&!is_dir($archiveDirectory))throw new \RuntimeException('export_unavailable');if(!is_writable($archiveDirectory))throw new \RuntimeException('export_unavailable');
        $products=count($rows);$changes=0;$applied=0;$pending=0;$priceProducts=array_fill(1,5,0);foreach($rows as $row){$selected=0;for($n=1;$n<=5;$n++){if((int)$row['MCP021_Selecionado_'.$n]){$selected++;$priceProducts[$n]++;}}$changes+=$selected;if($row['MCP021_Status']==='applied')$applied+=$selected;elseif($row['MCP021_Status']!=='ready')$pending+=$selected;}$activePrices=array_keys(array_filter($priceProducts));
        $book=new Spreadsheet();$summary=$book->getActiveSheet();$summary->setTitle('Resumo');$summary->setShowGridlines(false);
        $summary->mergeCells('A1:F1');$summary->setCellValue('A1','Relatório de atualização de preços');$summary->mergeCells('A2:F2');$summary->setCellValue('A2','Conferência do lote e das alterações registradas no histórico.');
        $summary->mergeCells('A4:B4');$summary->mergeCells('C4:D4');$summary->mergeCells('E4:F4');$summary->setCellValue('A4','Produtos no lote');$summary->setCellValue('C4','Alterações de preço');$summary->setCellValue('E4','Situação do lote');$summary->mergeCells('A5:B5');$summary->mergeCells('C5:D5');$summary->mergeCells('E5:F5');$summary->setCellValue('A5',$products);$summary->setCellValue('C5',$changes);$summary->setCellValue('E5',$this->statusLabel($batch['MCP020_Status']));
        $summary->mergeCells('A7:C7');$summary->mergeCells('D7:F7');$summary->setCellValue('A7','Identificação do lote');$summary->setCellValue('D7','Auditoria');
        foreach([[8,'Lote',$batch['MCP020_Public_Id']],[9,'Usuário responsável',$batch['actor_name']],[10,'Tipo',$this->typeLabel($batch['MCP020_Tipo'])],[11,'Origem',$this->originLabel($batch['MCP020_Origem'])]] as $entry){$summary->setCellValue('A'.$entry[0],$entry[1]);$summary->mergeCells('B'.$entry[0].':C'.$entry[0]);$summary->setCellValue('B'.$entry[0],$entry[2]);}
        foreach([[8,'Criado em',$this->dateTimeLabel($batch['MCP020_Data_Criacao'])],[9,'Concluído em',$this->dateTimeLabel($batch['MCP020_Data_Conclusao'])],[10,'Planilha gerada em',$this->dateTimeLabel(gmdate('Y-m-d H:i:s'))],[11,'Alterações aplicadas / pendentes',$applied.' / '.$pending],[12,'Preços alterados',$this->priceSummary($priceProducts)]] as $entry){$summary->setCellValue('D'.$entry[0],$entry[1]);$summary->mergeCells('E'.$entry[0].':F'.$entry[0]);$summary->setCellValue('E'.$entry[0],$entry[2]);}
        $summary->getStyle('A1:F1')->getFont()->setBold(true)->setSize(16)->getColor()->setRGB('FFFFFF');$summary->getStyle('A1:F1')->getFill()->setFillType('solid')->getStartColor()->setRGB('1F4E78');$summary->getStyle('A2:F2')->getFont()->setItalic(true)->getColor()->setRGB('5B6573');
        foreach(['A4:B4'=>'D9EAF7','C4:D4'=>'E2F0D9','E4:F4'=>'E2F0D9','A5:B5'=>'EDF4FB','C5:D5'=>'EDF7EA','E5:F5'=>$this->statusColor((string)$batch['MCP020_Status'])] as $range=>$color){$summary->getStyle($range)->getFill()->setFillType('solid')->getStartColor()->setRGB($color);$summary->getStyle($range)->getAlignment()->setHorizontal('center')->setVertical('center');}$summary->getStyle('A4:F4')->getFont()->setBold(true)->getColor()->setRGB('1F1F1F');$summary->getStyle('A5:F5')->getFont()->setBold(true)->setSize(15)->getColor()->setRGB('1F1F1F');
        foreach(['A7:C7','D7:F7'] as $range){$summary->getStyle($range)->getFill()->setFillType('solid')->getStartColor()->setRGB('D9E2F3');$summary->getStyle($range)->getFont()->setBold(true)->getColor()->setRGB('1F4E78');}$summary->getStyle('A8:A11')->getFont()->setBold(true);$summary->getStyle('D8:D12')->getFont()->setBold(true);foreach(['A8:C11','D8:F12'] as $range){$summary->getStyle($range)->getBorders()->getAllBorders()->setBorderStyle('thin')->getColor()->setRGB('D9E2F3');$summary->getStyle($range)->getAlignment()->setWrapText(true)->setVertical('center');}
        $summary->getColumnDimension('A')->setWidth(23);$summary->getColumnDimension('B')->setWidth(22);$summary->getColumnDimension('C')->setWidth(18);$summary->getColumnDimension('D')->setWidth(25);$summary->getColumnDimension('E')->setWidth(22);$summary->getColumnDimension('F')->setWidth(18);$summary->getRowDimension(1)->setRowHeight(28);$summary->getRowDimension(2)->setRowHeight(22);$summary->getRowDimension(4)->setRowHeight(22);$summary->getRowDimension(5)->setRowHeight(28);

        $items=$book->createSheet();$items->setTitle('Conferência');$items->mergeCells('A1:B1');$items->setCellValue('A1','Produto');
        $colors=[1=>'5B9BD5',2=>'70AD47',3=>'8064A2',4=>'ED7D31',5=>'4472C4'];$bodyColors=[1=>'EDF4FB',2=>'EDF7EA',3=>'F2EDF7',4=>'FDF1E8',5=>'EAF0FA'];$columns=[];$column=3;
        foreach($activePrices as $n){ $start=$this->columnLetter($column);$end=$this->columnLetter($column+3);$items->mergeCells($start.'1:'.$end.'1');$items->setCellValue($start.'1','Preço '.$n);$items->fromArray(['Preço '.$n.' — Valor anterior','Preço '.$n.' — Novo valor','Preço '.$n.' — Diferença em reais','Preço '.$n.' — Diferença percentual'],null,$start.'2');$items->getStyle($start.'1:'.$end.'2')->getFill()->setFillType('solid')->getStartColor()->setRGB($colors[$n]);$items->getStyle($start.'1:'.$end.'2')->getFont()->setBold(true)->getColor()->setRGB('FFFFFF');$columns[$n]=$column;$column+=4; }
        $items->setCellValue('A2','Código do produto');$items->setCellValue('B2','Situação');$items->getStyle('A1:B2')->getFill()->setFillType('solid')->getStartColor()->setRGB('1F4E78');$items->getStyle('A1:B2')->getFont()->setBold(true)->getColor()->setRGB('FFFFFF');
        $lastColumn=$this->columnLetter($column-1);$lastRow=max(3,count($rows)+2);$items->getStyle('A1:'.$lastColumn.'2')->getAlignment()->setHorizontal('center')->setVertical('center')->setWrapText(true);$items->getRowDimension(1)->setRowHeight(24);$items->getRowDimension(2)->setRowHeight(44);$items->freezePane('C3');$items->setAutoFilter('A2:'.$lastColumn.$lastRow);$items->getColumnDimension('A')->setWidth(18);$items->getColumnDimension('B')->setWidth(15);
        foreach($columns as $n=>$start){$startColumn=$this->columnLetter($start);$endColumn=$this->columnLetter($start+3);foreach([$start,$start+1]as $i)$items->getColumnDimension($this->columnLetter($i))->setWidth(19);$items->getColumnDimension($this->columnLetter($start+2))->setWidth(22);$items->getColumnDimension($this->columnLetter($start+3))->setWidth(24);$items->getStyle($startColumn.'3:'.$endColumn.$lastRow)->getFill()->setFillType('solid')->getStartColor()->setRGB($bodyColors[$n]);$items->getStyle($startColumn.'1:'.$endColumn.$lastRow)->getBorders()->getLeft()->setBorderStyle('medium')->getColor()->setRGB($colors[$n]);$items->getStyle($startColumn.'1:'.$endColumn.$lastRow)->getBorders()->getRight()->setBorderStyle('medium')->getColor()->setRGB($colors[$n]);}
        $line=3;foreach($rows as $row){$items->setCellValueExplicit('A'.$line,(string)$row['MCP021_Codigo_Produto'],DataType::TYPE_STRING);$status=$this->statusLabel((string)$row['MCP021_Status']);$items->setCellValue('B'.$line,$status);$items->getStyle('B'.$line)->getFill()->setFillType('solid')->getStartColor()->setRGB($this->statusColor((string)$row['MCP021_Status']));
            for($n=1;$n<=5;$n++){if(!(int)$row['MCP021_Selecionado_'.$n])continue;$before=(float)$row['MCP021_Preco_'.$n.'_Antes'];$after=(float)$row['MCP021_Preco_'.$n.'_Depois'];$start=$columns[$n];$beforeCell=$this->columnLetter($start).$line;$afterCell=$this->columnLetter($start+1).$line;$diffCell=$this->columnLetter($start+2).$line;$percentCell=$this->columnLetter($start+3).$line;$items->setCellValueExplicit($beforeCell,$before,DataType::TYPE_NUMERIC);$items->setCellValueExplicit($afterCell,$after,DataType::TYPE_NUMERIC);$items->setCellValueExplicit($diffCell,$after-$before,DataType::TYPE_NUMERIC);if($before!=0.0)$items->setCellValueExplicit($percentCell,($after-$before)/$before,DataType::TYPE_NUMERIC);$items->getStyle($beforeCell.':'.$diffCell)->getNumberFormat()->setFormatCode('[$R$-pt-BR] #,##0.00########');$items->getStyle($percentCell)->getNumberFormat()->setFormatCode('0.00%;[Red]-0.00%');$items->getStyle($afterCell)->getFont()->setBold(true);if($after==0.0)$items->getStyle($afterCell)->getFill()->setFillType('solid')->getStartColor()->setRGB('FCE4D6');}
            $items->getStyle('A'.$line.':'.$lastColumn.$line)->getBorders()->getBottom()->setBorderStyle('hair')->getColor()->setRGB('D9E2F3');$line++;}
        $archivePath=$archiveDirectory.'/'.$batch['MCP020_Public_Id'].'.xlsx';$lock=fopen($archivePath.'.lock','c');if($lock===false||!flock($lock,LOCK_EX))throw new \RuntimeException('export_unavailable');try{if(!is_file($archivePath)){$temporary=$archivePath.'.'.bin2hex(random_bytes(8)).'.tmp';try{(new Xlsx($book))->save($temporary);if(!rename($temporary,$archivePath))throw new \RuntimeException('export_unavailable');}catch(\Throwable $e){if(is_file($temporary??''))unlink($temporary);throw new \RuntimeException('export_unavailable');}}}finally{flock($lock,LOCK_UN);fclose($lock);}
        $name='mcp-price-report-'.bin2hex(random_bytes(24)).'.xlsx';$path=$this->shareDirectory.'/'.$name;if(!@link($archivePath,$path)&&!copy($archivePath,$path))throw new \RuntimeException('export_unavailable');
        return ['batch_id'=>$batch['MCP020_Public_Id'],'format'=>'xlsx','download_url'=>rtrim($this->tenant->getRootUrl(),'/').'/hardness3/whatsapp/'.$name,'items'=>count($rows)];
    }
    private function query(string $sql,array $params=[]):\PDOStatement{$s=$this->pdo->prepare($sql);$s->execute($params);return $s;}
    private function columnLetter(int $column): string { $out='';while($column>0){$column--; $out=chr(65+($column%26)).$out;$column=intdiv($column,26);}return $out; }
    private function statusLabel(string $status): string { return ['applied'=>'Aplicado','conflict'=>'Conflito','blocked'=>'Bloqueado','failed'=>'Falha','ready'=>'Pendente','prepared'=>'Preparado','completed'=>'Concluído'][$status]??$status; }
    private function statusColor(string $status): string { return ['applied'=>'E2F0D9','completed'=>'E2F0D9','conflict'=>'FCE4D6','blocked'=>'FFF2CC','failed'=>'FCE4D6','ready'=>'D9EAF7','prepared'=>'D9EAF7'][$status]??'FFFFFF'; }
    private function typeLabel(string $type): string { return $type==='reversal'?'Reversão':'Atualização de preços'; }
    private function originLabel(string $origin): string { return $origin==='spreadsheet'?'Planilha':($origin==='manual'?'Manual':$origin); }
    private function priceSummary(array $counts): string { $parts=[];foreach($counts as $price=>$products)if($products>0)$parts[]='Preço '.$price.' ('.$products.' '.($products===1?'produto':'produtos').')';return $parts===[]?'—':implode(', ',$parts); }
    private function archiveDirectory(array $batch): string { $date=$batch['MCP020_Data_Conclusao']??$batch['MCP020_Data_Criacao'];$date=\DateTimeImmutable::createFromFormat('Y-m-d H:i:s',(string)$date,new \DateTimeZone('UTC'));$month=$date===false?gmdate('Y-m'):$date->format('Y-m');$database=preg_replace('/[^A-Za-z0-9_-]/','',$this->tenant->getDatabase())??'';if($database==='')throw new \RuntimeException('export_unavailable');return $this->erpRootPath.'/dados_usuarios/'.$database.'/mcp/AtualizacaoPreco/'.$month; }
    private function dateTimeLabel($value): string { if($value===null||$value==='')return '—';$date=\DateTimeImmutable::createFromFormat('Y-m-d H:i:s',(string)$value,new \DateTimeZone('UTC'));return $date===false?(string)$value:$date->format('d/m/Y H:i'); }
    private function actorName(array $actor,int $id): string { foreach(['C007_Nome','C007_Login'] as $field){$value=trim((string)($actor[$field]??''));if($value!=='')return $value;}return 'Usuário #'.$id; }
}
